import{_ as t,a as o,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Theme Customizations","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/theme-customizations/index.md","filePath":"api/rest-api/shop/theme-customizations/index.md","lastUpdated":1786429091000}'),d={name:"api/rest-api/shop/theme-customizations/index.md"};function r(i,e,n,c,h,l){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="theme-customizations" tabindex="-1">Theme Customizations <a class="header-anchor" href="#theme-customizations" aria-label="Permalink to &quot;Theme Customizations&quot;">​</a></h1><p>The Theme Customizations menu returns the content blocks an admin has configured for the storefront — image carousels, static-content sections, product/category carousels, footer link sets and similar homepage pieces. Use it to render the storefront&#39;s home and content areas from your own front end instead of hard-coding them.</p><h2 id="when-a-client-uses-this" tabindex="-1">When a client uses this <a class="header-anchor" href="#when-a-client-uses-this" aria-label="Permalink to &quot;When a client uses this&quot;">​</a></h2><p>Fetch the theme customizations for the current channel when building the homepage or any themed landing area. Each block carries its type and its per-locale content, so a client can lay out the same sections the storefront theme shows, in the shopper&#39;s language.</p><h2 id="how-to-render-the-home-page" tabindex="-1">How to render the home page <a class="header-anchor" href="#how-to-render-the-home-page" aria-label="Permalink to &quot;How to render the home page&quot;">​</a></h2><ol><li><strong>Fetch</strong> <code>GET /api/shop/theme-customizations</code> (optionally <code>?channelId=</code> / <code>?type=</code>). Keep only blocks with <code>status = 1</code>.</li><li><strong>Order</strong> the blocks by <code>sortOrder</code> — that is the top-to-bottom layout order.</li><li>For each block, <strong><code>JSON.parse(translation.options)</code></strong> and render by <code>type</code>:</li></ol><table tabindex="0"><thead><tr><th>Type</th><th>How to render</th><th>Needs a second call?</th></tr></thead><tbody><tr><td><code>image_carousel</code></td><td>Render <code>options.images[]</code> as slides — <code>image</code> = source, <code>link</code> = href, <code>title</code> = alt.</td><td>No — self-contained</td></tr><tr><td><code>static_content</code></td><td>Inject <code>options.html</code> and <code>options.css</code> directly.</td><td>No — self-contained</td></tr><tr><td><code>footer_links</code></td><td>Render <code>options.column_N[]</code> as footer link columns.</td><td>No — self-contained</td></tr><tr><td><code>services_content</code></td><td>Render <code>options.services[]</code> (<code>service_icon</code> / <code>title</code> / <code>description</code>).</td><td>No — self-contained</td></tr><tr><td><code>product_carousel</code></td><td>Send <code>options.filters</code> as query params to <code>GET /api/shop/products</code>, render the returned products under <code>options.title</code>.</td><td><strong>Yes → <a href="/api/rest-api/shop/products/search-product.html">Products</a></strong></td></tr><tr><td><code>category_carousel</code></td><td>Call <code>GET /api/shop/categories?parent_id={options.filters.parent_id}</code> (or the <a href="/api/rest-api/shop/categories/get-categories.html">category tree</a>), render the categories under <code>options.title</code>.</td><td><strong>Yes → <a href="/api/rest-api/shop/categories/get-categories.html">Categories</a></strong></td></tr></tbody></table><p>The blocks split into two kinds. <code>image_carousel</code>, <code>static_content</code>, <code>footer_links</code> and <code>services_content</code> are self-contained — render straight from <code>options</code>. <code>product_carousel</code> and <code>category_carousel</code> are only <em>configuration</em>: their <code>options.filters</code> tell you what to request from the Products / Categories endpoints — the block itself carries no products or categories.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/theme-customizations/get-theme-customizations.html">Theme Customizations</a></td><td><code>GET /api/shop/theme-customizations</code></td><td>List the configured storefront content blocks.</td></tr></tbody></table><p>All Theme Customization endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',11)]))}const u=t(d,[["render",r]]);export{m as __pageData,u as default};
